<?php
declare(strict_types=1);
/**
 * Linux-only synthetic DB + HTTP authorization/storage tests.
 * Ed25519 manifest signatures below are real Sodium signatures. OpenPGP public
 * fixtures were generated by pinned OpenPGP.js 6.3.2; no private PGP key is kept.
 * Message/recovery/attachment bytes are deliberately opaque SERVER test data,
 * not valid PGP encryption. Actual encryption is tested separately in JS/browser.
 */
if (PHP_SAPI!=='cli'||PHP_OS_FAMILY==='Windows'||getenv('DB_DATABASE')!=='gunindex_rebuild_test') exit(2);
require_once __DIR__.'/../config/bootstrap.php';
require_once __DIR__.'/../config/e2ee.php';
if ($pdo->query('SELECT DATABASE()')->fetchColumn()!=='gunindex_rebuild_test') exit(2);

function eit_check(bool $ok,string $reason='assertion'): void {
    if (!$ok) throw new RuntimeException('E2EE synthetic test failed: '.$reason);
}
function eit_test(string $name,callable $run): void {
    global $eitPassed;
    try { $run(); ++$eitPassed; echo 'PASS '.$name.PHP_EOL; }
    catch (Throwable $error) {
        fwrite(STDERR,'FAIL '.$name.' ('.get_class($error).' at '.basename($error->getFile()).':'.$error->getLine().')'.PHP_EOL);
        throw $error;
    }
}
function eit_scalar(PDO $pdo,string $sql,array $params=[]): mixed {
    $q=$pdo->prepare($sql); $q->execute($params); return $q->fetchColumn();
}
function eit_reject(callable $run,string $expected): void {
    try { $run(); } catch (Throwable $error) { eit_check($error instanceof $expected,'exception class'); return; }
    throw new LogicException('Expected operation rejection.');
}
