function eit_user(PDO $pdo,string $role): array {
    $name='e2eit_'.bin2hex(random_bytes(12)).'_'.$role;
    $password='Synthetic E2EE '.bin2hex(random_bytes(16));
    $pdo->prepare("INSERT INTO users(username,email,password_hash,full_name,zip,city,country_code,preferred_locale) VALUES (?,?,?,'Synthetic E2EE integration fixture','10115','Synthetic town','DE','de')")
        ->execute([$name,$name.'@example.invalid',auth_hash($password)]);
    $pair=sodium_crypto_sign_keypair();
    return ['id'=>(int)$pdo->lastInsertId(),'username'=>$name,'password'=>$password,
        'identity'=>base64_encode(sodium_crypto_sign_publickey($pair)),'secret'=>sodium_crypto_sign_secretkey($pair),
        'version'=>0,'hash'=>str_repeat('0',64),'devices'=>[]];
}
function eit_device(int $keyIndex): array {
    return ['id'=>bin2hex(random_bytes(16)),'name'=>'Synthetic test device '.($keyIndex+1)]+eit_public_keys()[$keyIndex]+['revoked'=>false];
}
function eit_manifest(array $user,array $devices,int $recoveryKey=2): array {
    $recovery=random_bytes(192); // opaque server fixture; not an encrypted recovery export
    $value=['protocol'=>'gunindex-devices-1','user_id'=>$user['id'],'version'=>$user['version']+1,
        'previous_hash'=>$user['hash'],'identity_key'=>$user['identity'],'recovery_public'=>eit_public_keys()[$recoveryKey]['public_key'],
        'recovery_hash'=>hash('sha256',$recovery),'devices'=>$devices];
    return eit_sign($user,$value,base64_encode($recovery));
}
function eit_sign(array $user,array $value,string $recovery): array {
    $manifest=json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    return ['expected_version'=>$user['version'],'expected_hash'=>$user['hash'],'manifest'=>$manifest,
        'signature'=>base64_encode(sodium_crypto_sign_detached("GunIndex device manifest v1\0".$manifest,$user['secret'])),
        'recovery_cipher'=>$recovery];
}
function eit_http(CurlHandle $curl,string $path,?array $payload=null,bool $json=true,array $headers=[]): array {
    $responseHeaders=[];
    curl_setopt_array($curl,[CURLOPT_URL=>'http://127.0.0.1:8081'.$path,CURLOPT_HEADERFUNCTION=>static function($handle,string $line)use(&$responseHeaders):int {
        if (str_contains($line,':')) { [$key,$value]=explode(':',$line,2); $responseHeaders[strtolower(trim($key))]=trim($value); }
        return strlen($line);
    }]);
    if ($payload===null) curl_setopt($curl,CURLOPT_HTTPGET,true);
    else {
        curl_setopt($curl,CURLOPT_POST,true);
        curl_setopt($curl,CURLOPT_POSTFIELDS,$json?json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES):http_build_query($payload));
        $headers[]='Content-Type: '.($json?'application/json':'application/x-www-form-urlencoded');
    }
    curl_setopt($curl,CURLOPT_HTTPHEADER,$headers);
    $body=curl_exec($curl); eit_check(is_string($body),'HTTP transport');
    $data=str_starts_with($responseHeaders['content-type']??'','application/json')?json_decode($body,true,32,JSON_THROW_ON_ERROR):null;
    return ['status'=>(int)curl_getinfo($curl,CURLINFO_RESPONSE_CODE),'body'=>$body,'data'=>$data,'headers'=>$responseHeaders];
}
function eit_token(string $body): string {
    eit_check(preg_match('/name="csrf_token"\s+value="([a-f0-9]{64})"/',$body,$matches)===1,'CSRF in authenticated page');
    return $matches[1];
}
function eit_browser(?array $user=null): array {
    $curl=curl_init(); eit_check($curl instanceof CurlHandle,'curl init');
    curl_setopt_array($curl,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_PROXY=>'',CURLOPT_TIMEOUT=>30,CURLOPT_FOLLOWLOCATION=>false]);
    if ($user===null) return ['curl'=>$curl,'csrf'=>''];
    $login=eit_http($curl,'/auth/login.php'); eit_check($login['status']===200,'login form');
    $response=eit_http($curl,'/auth/login.php',['csrf_token'=>eit_token($login['body']),'login'=>$user['username'],'password'=>$user['password']],false);
    eit_check($response['status']===303,'login success');
    $profile=eit_http($curl,'/user/profile.php'); eit_check($profile['status']===200,'authenticated profile');
    return ['curl'=>$curl,'csrf'=>eit_token($profile['body'])];
}
function eit_post(array $browser,string $action,array $payload,int $status=200): array {
    $response=eit_http($browser['curl'],'/user/e2ee-api.php',['action'=>$action,'csrf_token'=>$browser['csrf']]+$payload);
    eit_check($response['status']===$status,$action.' HTTP '.$status.' actual '.$response['status']);
    eit_check(is_array($response['data']),'JSON response'); return $response['data'];
}
function eit_get(array $browser,string $action,array $query=[],int $status=200): array {
    $response=eit_http($browser['curl'],'/user/e2ee-api.php?'.http_build_query(['action'=>$action]+$query));
    eit_check($response['status']===$status,$action.' HTTP '.$status.' actual '.$response['status']); return $response;
}
function eit_accept(array &$user,array $browser,array $input): void {
    $result=eit_post($browser,'account',$input)['account'];
    eit_check($result['manifest']===$input['manifest']&&$result['signature']===$input['signature']&&$result['recovery_cipher']===$input['recovery_cipher'],'exact manifest round trip');
    $value=json_decode($input['manifest'],true,32,JSON_THROW_ON_ERROR);
    $user['hash']=hash('sha256',$input['manifest']); eit_check($result['hash']===$user['hash'],'manifest hash');
    $user['version']=$value['version']; $user['devices']=$value['devices'];
}
function eit_message(array $from,array $to,int $listing,?string $client=null,array $attachments=[]): array {
    $devices=array_values(array_filter($from['devices'],static fn(array $d):bool=>!$d['revoked']));
    return ['listing_id'=>$listing,'peer_id'=>$to['id'],'device_id'=>$devices[0]['id'],'client_id'=>$client??bin2hex(random_bytes(16)),
        'sender_version'=>$from['version'],'receiver_version'=>$to['version'],'ciphertext'=>base64_encode(random_bytes(192)),'attachments'=>$attachments];
}
function eit_upload_payload(array $from,array $to,int $listing,string $client,string $bytes): array {
    $message=eit_message($from,$to,$listing,$client);
    return array_intersect_key($message,array_flip(['listing_id','peer_id','device_id','client_id']))+['id'=>bin2hex(random_bytes(16)),'ciphertext'=>base64_encode($bytes)];
}

// Independent PHP workers exercise CAS against real concurrent DB connections.
if (($argv[1]??'')==='--cas-worker') {
    try {
        $input=json_decode(stream_get_contents(STDIN,32769),true,24,JSON_THROW_ON_ERROR);
        eit_check(is_array($input)&&is_int($input['user']??null)&&is_array($input['request']??null));
        eit_check((int)eit_scalar($pdo,"SELECT COUNT(*) FROM users WHERE id=? AND username LIKE 'e2eit\\_%' AND full_name='Synthetic E2EE integration fixture' AND email=CONCAT(username,'@example.invalid') AND is_admin=0",[$input['user']])===1);
        $start=$input['start']??null; eit_check(is_numeric($start)&&$start<=microtime(true)+2);
        while (microtime(true)<$start) usleep(2000);
        try { $saved=e2ee_account_save($pdo,$input['user'],$input['request']); echo json_encode(['status'=>200,'hash'=>$saved['hash']],JSON_THROW_ON_ERROR); }
        catch (E2EEConflictException) { echo '{"status":409}'; }
        exit(0);
    } catch (Throwable) { fwrite(STDERR,'Synthetic E2EE CAS worker failed.'.PHP_EOL); exit(1); }
}

$eitPassed=0; $browsers=[];
try {
    eit_check(e2ee_enabled()&&extension_loaded('sodium')&&geo_country_enabled($pdo,'DE'),'isolated E2EE runtime configured');
    $seller=eit_user($pdo,'seller'); $buyer=eit_user($pdo,'buyer'); $outsider=eit_user($pdo,'outsider');
    $pdo->prepare('INSERT INTO market_categories(name,slug) VALUES (?,?)')->execute(['Synthetic E2EE desks','e2eit-'.bin2hex(random_bytes(16))]);
    $category=(int)$pdo->lastInsertId();
    $pdo->prepare("INSERT INTO market_listings(seller_id,category_id,title,description,type,price_cents,status,zip,city,country_code) VALUES (?,?,'Synthetic E2EE folding desk','Ordinary synthetic folding desk for isolated encrypted chat regression tests.','fixed',4500,'active','10115','Synthetic town','DE')")->execute([$seller['id'],$category]);
    $listing=(int)$pdo->lastInsertId();
    $legacy='Synthetic preserved legacy '.bin2hex(random_bytes(16));
    $legacyId=chat_send($pdo,$buyer['id'],$listing,$seller['id'],$legacy);
    $browsers['seller']=eit_browser($seller); $browsers['buyer']=eit_browser($buyer); $browsers['outsider']=eit_browser($outsider); $browsers['guest']=eit_browser();

    eit_test('authenticated_json_csrf_origin_and_exact_request_schema',static function()use($pdo,$buyer,$browsers):void {
        eit_get($browsers['guest'],'account',[],401);
        $response=eit_http($browsers['buyer']['curl'],'/user/e2ee-api.php',['action'=>'account']); eit_check($response['status']===403);
        $response=eit_http($browsers['buyer']['curl'],'/user/e2ee-api.php',['action'=>'account','csrf_token'=>$browsers['buyer']['csrf']],true,['Origin: https://untrusted.example.invalid']); eit_check($response['status']===403);
        $request=eit_manifest($buyer,[eit_device(0)]);
        eit_post($browsers['buyer'],'account',$request+['private_key'=>'Forbidden plaintext field'],400);
        eit_get($browsers['buyer'],'account',['user_id'=>$buyer['id']],400);
        eit_check(eit_get($browsers['buyer'],'account')['data']['account']===null);
        eit_check((int)eit_scalar($pdo,'SELECT COUNT(*) FROM market_e2ee_accounts WHERE user_id=?',[$buyer['id']])===0);
    });

    eit_test('real_signed_account_enrollment_idempotency_and_private_recovery_access',static function()use(&$seller,&$buyer,&$outsider,$browsers,$listing):void {
        $request=eit_manifest($buyer,[eit_device(0)]); eit_accept($buyer,$browsers['buyer'],$request);
        eit_post($browsers['buyer'],'account',$request); // exact retry, no new version
        eit_post($browsers['seller'],'account',$request,400); // signed user id cannot be reassigned
        eit_accept($seller,$browsers['seller'],eit_manifest($seller,[eit_device(1)]));
        eit_accept($outsider,$browsers['outsider'],eit_manifest($outsider,[eit_device(0)]));
        $own=eit_get($browsers['buyer'],'account'); eit_check($own['data']['account']['recovery_cipher']===$request['recovery_cipher']);
        eit_check(str_contains($own['headers']['cache-control']??'','no-store'));
        $context=eit_get($browsers['buyer'],'context',['listing_id'=>$listing,'peer_id'=>$seller['id']])['data'];
        eit_check($context['can_send']===true&&$context['self']['hash']===$buyer['hash']&&$context['peer']['hash']===$seller['hash']);
        eit_check(!isset($context['self']['recovery_cipher'])&&!isset($context['peer']['recovery_cipher']));
        eit_get($browsers['outsider'],'context',['listing_id'=>$listing,'peer_id'=>$buyer['id']],403);
    });

    eit_test('signature_recovery_digest_stale_cas_and_identity_replacement_rejected',static function()use($pdo,$buyer,$browsers):void {
        $request=eit_manifest($buyer,$buyer['devices'],3);
        $invalid=$request; $signature=base64_decode($invalid['signature'],true); $signature[0]=chr(ord($signature[0])^1); $invalid['signature']=base64_encode($signature);
        eit_post($browsers['buyer'],'account',$invalid,400);
        $invalid=$request; $invalid['recovery_cipher']=base64_encode(random_bytes(192)); eit_post($browsers['buyer'],'account',$invalid,400);
        $value=json_decode($request['manifest'],true,32,JSON_THROW_ON_ERROR);
        $stale=$buyer; $stale['version']=0; $stale['hash']=str_repeat('0',64); $value['version']=1; $value['previous_hash']=$stale['hash'];
        eit_post($browsers['buyer'],'account',eit_sign($stale,$value,$request['recovery_cipher']),409);
        $otherAuthority=$buyer; $pair=sodium_crypto_sign_keypair(); $otherAuthority['secret']=sodium_crypto_sign_secretkey($pair); $otherAuthority['identity']=base64_encode(sodium_crypto_sign_publickey($pair));
        eit_post($browsers['buyer'],'account',eit_manifest($otherAuthority,$buyer['devices'],3),409);
        eit_check(eit_scalar($pdo,'SELECT current_hash FROM market_e2ee_accounts WHERE user_id=?',[$buyer['id']])===$buyer['hash']);
        eit_check((int)eit_scalar($pdo,'SELECT COUNT(*) FROM market_e2ee_manifests WHERE user_id=?',[$buyer['id']])===1);
    });

    $firstMessage=null; $firstRequest=null;
    eit_test('opaque_envelope_idempotency_storage_historical_access_and_read_scope',static function()use($pdo,$buyer,$seller,$browsers,$listing,$legacyId,&$firstMessage,&$firstRequest):void {
        $firstRequest=eit_message($buyer,$seller,$listing);
        $firstMessage=eit_post($browsers['buyer'],'send',$firstRequest)['id']; eit_check(is_int($firstMessage)&&$firstMessage>0);
        eit_check(eit_post($browsers['buyer'],'send',$firstRequest)['id']===$firstMessage);
        $altered=$firstRequest; $altered['ciphertext']=base64_encode(random_bytes(192)); eit_post($browsers['buyer'],'send',$altered,409);
        $q=$pdo->prepare('SELECT m.message_text,m.cipher_version,e.ciphertext FROM market_messages m JOIN market_e2ee_messages e ON e.message_id=m.id WHERE m.id=?'); $q->execute([$firstMessage]); $row=$q->fetch();
        eit_check($row['message_text']===''&&(int)$row['cipher_version']===2&&$row['ciphertext']===$firstRequest['ciphertext']);
        eit_check((int)eit_scalar($pdo,'SELECT COUNT(*) FROM market_e2ee_messages WHERE sender_id=? AND client_id=?',[$buyer['id'],$firstRequest['client_id']])===1);
        $rows=eit_get($browsers['seller'],'history',['listing_id'=>$listing,'peer_id'=>$buyer['id']])['data']['messages'];
        eit_check(count($rows)===1&&$rows[0]['id']===$firstMessage&&$rows[0]['sender_manifest']['hash']===$buyer['hash']&&$rows[0]['receiver_manifest']['hash']===$seller['hash']);
        eit_check(!isset($rows[0]['sender_manifest']['recovery_cipher'])&&!isset($rows[0]['message_text']));
        eit_get($browsers['outsider'],'history',['listing_id'=>$listing,'peer_id'=>$buyer['id']],403);
        $reply=eit_post($browsers['seller'],'send',eit_message($seller,$buyer,$listing))['id'];
        $read=['listing_id'=>$listing,'peer_id'=>$buyer['id'],'through'=>$reply];
        eit_post($browsers['outsider'],'read',$read,403);
        $invalid=$read; $invalid['through']=[$reply]; eit_post($browsers['seller'],'read',$invalid,400);
        $invalid=$read; $invalid['through']=$legacyId; eit_post($browsers['seller'],'read',$invalid,404);
        $invalid=$read; $invalid['peer_id']=$seller['id']; eit_post($browsers['outsider'],'read',$invalid,404);
        eit_check(eit_post($browsers['seller'],'read',$read)['read']===1);
        eit_check(eit_post($browsers['seller'],'read',$read)['read']===0);
        eit_check((int)eit_scalar($pdo,'SELECT is_read FROM market_messages WHERE id=?',[$firstMessage])===1);
        eit_check((int)eit_scalar($pdo,'SELECT is_read FROM market_messages WHERE id=?',[$reply])===0);
        eit_check((int)eit_scalar($pdo,'SELECT is_read FROM market_messages WHERE id=?',[$legacyId])===0);
    });

    eit_test('append_device_revoke_immutability_and_old_message_history_preserved',static function()use($pdo,&$buyer,$seller,$browsers,$listing,$firstMessage):void {
        $oldHash=$buyer['hash']; $oldDevice=$buyer['devices'][0];
        $devices=[$oldDevice,eit_device(1)]; eit_accept($buyer,$browsers['buyer'],eit_manifest($buyer,$devices,3));
        $devices[0]['revoked']=true; eit_accept($buyer,$browsers['buyer'],eit_manifest($buyer,$devices,2));
