    eit_test('privacy_export_preserves_mixed_history_and_opaque_files_without_recovery_secrets',static function()use($pdo,$buyer,$seller,$outsider,$browsers,$listing,$legacyId,$legacy,$firstMessage,$firstRequest,$attachment,$attachmentBytes):void {
