            eit_check(!str_contains($raw,'"recovery_cipher"')&&!str_contains($raw,'"storage_key"')&&!str_contains($raw,'PRIVATE KEY BLOCK'));
            foreach ($data['e2ee_manifests'] as $manifest) eit_check((int)$manifest['user_id']===$buyer['id']);
