    eit_test('concurrent_signed_manifest_updates_have_exactly_one_cas_winner',static function()use($pdo,$outsider):void {
        eit_check(function_exists('proc_open'),'independent PHP workers available');
        $first=eit_manifest($outsider,$outsider['devices'],3); $second=eit_manifest($outsider,$outsider['devices'],3);
        $requests=[$first,$second]; $jobs=[]; $statuses=[]; $winnerHash=null;
        try {
            foreach ($requests as $request) {
                $process=proc_open([PHP_BINARY,__FILE__,'--cas-worker'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);
                eit_check(is_resource($process),'CAS worker started'); $jobs[]=['process'=>$process,'pipes'=>$pipes,'request'=>$request];
            }
            $start=microtime(true)+0.25;
            foreach ($jobs as $job) {
                $payload=json_encode(['user'=>$outsider['id'],'request'=>$job['request'],'start'=>$start],JSON_THROW_ON_ERROR);
                eit_check(fwrite($job['pipes'][0],$payload)===strlen($payload)); fclose($job['pipes'][0]);
            }
            foreach ($jobs as $index=>$job) {
                stream_set_timeout($job['pipes'][1],20); $raw=stream_get_contents($job['pipes'][1],2048); $metadata=stream_get_meta_data($job['pipes'][1]);
                eit_check(!$metadata['timed_out']&&is_string($raw),'CAS worker response');
                $answer=json_decode($raw,true,8,JSON_THROW_ON_ERROR); $statuses[]=$answer['status'];
                if ($answer['status']===200) $winnerHash=$answer['hash'];
                fclose($job['pipes'][1]); fclose($job['pipes'][2]); eit_check(proc_close($job['process'])===0); unset($jobs[$index]);
            }
        } finally {
            foreach ($jobs as $job) {
                foreach ($job['pipes'] as $pipe) if (is_resource($pipe)) fclose($pipe);
                if (is_resource($job['process'])) { proc_terminate($job['process']); proc_close($job['process']); }
            }
        }
        sort($statuses); eit_check($statuses===[200,409]);
        eit_check(eit_scalar($pdo,'SELECT current_hash FROM market_e2ee_accounts WHERE user_id=?',[$outsider['id']])===$winnerHash);
        eit_check((int)eit_scalar($pdo,'SELECT COUNT(*) FROM market_e2ee_manifests WHERE user_id=?',[$outsider['id']])===2);
    });

    eit_test('reauthenticated_identity_reset_preserves_history_and_requires_current_recipients',static function()use($pdo,$seller,$browsers,$listing):void {
        $owner=eit_user($pdo,'reset');
